<script lang="ts">
  import { onMount,tick } from 'svelte';
  import { invoke } from '@tauri-apps/api/core';
  import { copy } from './input-preferences';
  import { moveEntry } from './applications';
  import type { AppSettings,ApplicationsSnapshot } from './applications';
  import FileAssociations from './FileAssociations.svelte';
  let saved=$state<AppSettings|null>(null),draft=$state<AppSettings|null>(null),defaults=$state<AppSettings|null>(null),ruleOrigins=$state<(number|null)[]>([]),startupOrigins=$state<(number|null)[]>([]);
  let tab=$state('defaults'),busy=$state(false),loading=$state(true),error=$state(''),message=$state(''),resetPending=$state(false),startupPending=$state(false);
  let alive=true;
  let dirty=$derived(!!draft&&!!saved&&(JSON.stringify(draft)!==JSON.stringify(saved)||ruleOrigins.some((origin,index)=>origin!==index)||startupOrigins.some((origin,index)=>origin!==index)));
  const commands=[['terminal','Terminal','alacritty'],['browser','Web browser','google-chrome'],['file_manager','File manager','focaldesk-files'],['email','Email','Leave blank for automatic mail-client discovery']] as const;
  function accept(next:ApplicationsSnapshot){saved=copy(next.apps);draft=copy(next.apps);defaults=copy(next.defaults);ruleOrigins=next.apps.window_rules.map((_,index)=>index);startupOrigins=next.apps.startup_apps.map((_,index)=>index);resetPending=false;startupPending=false;}
  async function reload(){busy=true;error='';message='';try{const next=await invoke<ApplicationsSnapshot>('get_applications');if(alive)accept(next);}catch(cause){if(alive)error=String(cause);}finally{if(alive){busy=false;loading=false;}}}
  async function apply(confirmed=false){if(!draft||!saved||busy)return;if(!confirmed&&JSON.stringify(draft.startup_apps)!==JSON.stringify(saved.startup_apps)&&draft.startup_apps.some((app,index)=>app.enabled&&JSON.stringify(app)!==JSON.stringify(saved?.startup_apps[index]))){startupPending=true;return;}busy=true;error='';message='';startupPending=false;try{const next=await invoke<{snapshot:ApplicationsSnapshot;message:string}>('apply_applications',{change:{expected:copy(saved),requested:copy(draft),rule_origins:[...ruleOrigins],startup_origins:[...startupOrigins]}});if(alive){accept(next.snapshot);message=next.message;}}catch(cause){if(alive)error=String(cause);}finally{if(alive)busy=false;}}
  function discard(){if(saved){draft=copy(saved);ruleOrigins=saved.window_rules.map((_,index)=>index);startupOrigins=saved.startup_apps.map((_,index)=>index);}error='';message='';resetPending=false;startupPending=false;}
  async function addRule(){if(!draft||draft.window_rules.length>=64)return;draft.window_rules.push({app_id:'',title_contains:'',workspace:null,output:null,floating:null,maximize:null});ruleOrigins.push(null);await tick();document.getElementById(`rule-app-${draft.window_rules.length-1}`)?.focus();}
  async function addStartup(){if(!draft||draft.startup_apps.length>=64)return;draft.startup_apps.push({name:'',command:'',arguments:[],enabled:true});startupOrigins.push(null);await tick();document.getElementById(`startup-command-${draft.startup_apps.length-1}`)?.focus();}
  onMount(()=>{void reload();return()=>{alive=false;};});
</script>
<div class="page-heading"><div><div class="eyebrow">THE RIGHT APP FOR EVERY TASK</div><h1>Applications</h1><p>Choose launch defaults, file associations, and application behavior.</p></div><button class="quiet" disabled={busy} onclick={reload}>Reload applications</button></div>
{#if error}<div class="notice error" role="alert">{error}</div>{/if}{#if message}<div class="notice success" role="status">{message}</div>{/if}
<div class="application-tabs" role="group" aria-label="Application settings sections">{#each [['defaults','Defaults'],['associations','File associations'],['rules','Window rules'],['startup','Startup']] as [value,label]}<button aria-pressed={tab===value} class:active={tab===value} onclick={()=>tab=value}>{label}</button>{/each}</div>
{#if tab==='associations'}<FileAssociations />
{:else if loading}<div class="loading" role="status">Reading application preferences…</div>
{:else if draft}
{#if startupPending}<section class="applications-prompt" role="group" aria-label="Confirm startup changes"><h2>Save startup changes?</h2><p>Enabled startup entries run their configured executable and arguments at the next sign-in. Saving does not launch them now.</p><button class="quiet" onclick={()=>startupPending=false}>Keep editing startup</button><button class="quiet" onclick={()=>apply(true)}>Save startup changes</button></section>{/if}
{#if resetPending}<section class="applications-prompt" role="group" aria-label="Reset application settings"><h2>Restore built-in application settings?</h2><p>This resets launch commands and removes custom window rules and startup entries from your draft. Apply to save it.</p><button class="quiet" onclick={()=>resetPending=false}>Keep application settings</button><button class="quiet" onclick={()=>{if(defaults){draft=copy(defaults);ruleOrigins=defaults.window_rules.map(()=>null);startupOrigins=defaults.startup_apps.map(()=>null);}resetPending=false;}}>Reset application draft</button></section>{/if}
<fieldset disabled={busy} class="application-fields"><legend class="sr-only">FocalDesk application preferences</legend>
{#if tab==='defaults'}
  <section class="section"><h2>FocalDesk launch defaults</h2><p class="description">Executables used by desktop shortcuts and launch actions. File and link associations have their own tab.</p><div class="settings-card">{#each commands as [key,label,placeholder]}<div class="setting-row"><div><label for={`apps-${key}`}>{label}</label><p>{key==='email'?'A blank value discovers an available mail client.':'Enter an executable name or an absolute path.'}</p></div><input id={`apps-${key}`} type="text" maxlength="1024" {placeholder} bind:value={draft[key]} autocomplete="off" /></div>{/each}<div class="setting-row"><div><label for="apps-browser-backend">Browser backend</label><p>Auto prefers Wayland; XWayland is an explicit choice.</p></div><select id="apps-browser-backend" bind:value={draft.browser_launch_backend}><option value="auto">Auto</option><option value="wayland">Wayland</option><option value="xwayland">XWayland</option></select></div><div class="setting-row"><div><label for="apps-pin-email">Pin email to task shelf</label><p>Show Email with pinned applications when a mail client is available.</p></div><input id="apps-pin-email" class="switch" type="checkbox" role="switch" bind:checked={draft.pin_email_to_shelf} /></div></div></section>
  <section class="section"><h2>Restore defaults</h2><p class="description">Reset launch commands, window rules, and startup entries in this draft.</p><button class="quiet" onclick={()=>resetPending=true}>Reset application settings</button></section>
{:else if tab==='rules'}
  <section class="section"><div class="section-heading"><h2>Window rules</h2><button class="quiet" disabled={draft.window_rules.length>=64} onclick={addRule}>Add window rule</button></div><p class="description">The first matching rule wins for new windows. Application ID matches are case-insensitive; titles use a substring match. Session-restored windows keep their saved placement.</p>{#each draft.window_rules as rule,index}<details class="application-entry" open><summary>Rule {index+1} · {rule.app_id||rule.title_contains||'New window rule'}</summary><div class="entry-fields"><div class="setting-row"><label for={`rule-app-${index}`}>Application ID / X11 class</label><input id={`rule-app-${index}`} type="text" maxlength="256" bind:value={rule.app_id} /></div><div class="setting-row"><label for={`rule-title-${index}`}>Title contains</label><input id={`rule-title-${index}`} type="text" maxlength="256" bind:value={rule.title_contains} /></div><div class="setting-row"><div><label for={`rule-workspace-${index}`}>Workspace</label><p>0 keeps the current workspace.</p></div><input id={`rule-workspace-${index}`} type="number" min="0" max="99" value={rule.workspace??0} oninput={event=>rule.workspace=event.currentTarget.valueAsNumber>0?event.currentTarget.valueAsNumber:null} /></div><div class="setting-row"><div><label for={`rule-output-${index}`}>Display connector</label><p>Leave blank to keep the current display.</p></div><input id={`rule-output-${index}`} type="text" maxlength="256" value={rule.output??''} oninput={event=>rule.output=event.currentTarget.value||null} /></div>{#each [['floating','Floating'],['maximize','Maximize']] as [key,label]}<div class="setting-row"><label for={`rule-${key}-${index}`}>{label}</label><select id={`rule-${key}-${index}`} bind:value={rule[key as 'floating'|'maximize']}><option value={null}>Use default</option><option value={false}>No</option><option value={true}>Yes</option></select></div>{/each}<div class="entry-actions"><button class="quiet" aria-label={`Move window rule ${index+1} up`} disabled={index===0} onclick={()=>{if(draft)moveEntry(draft.window_rules,ruleOrigins,index,-1);}}>Move up</button><button class="quiet" aria-label={`Move window rule ${index+1} down`} disabled={index===draft.window_rules.length-1} onclick={()=>{if(draft)moveEntry(draft.window_rules,ruleOrigins,index,1);}}>Move down</button><button class="quiet" aria-label={`Remove window rule ${index+1}`} onclick={()=>{draft?.window_rules.splice(index,1);ruleOrigins.splice(index,1);}}>Remove</button></div></div></details>{:else}<div class="empty-applications">No custom window rules. Add a rule to choose how a new application window is placed.</div>{/each}</section>
{:else}
  <section class="section"><div class="section-heading"><h2>Startup applications</h2><button class="quiet" disabled={draft.startup_apps.length>=64} onclick={addStartup}>Add startup application</button></div><p class="description">Enabled entries launch once after sign-in, separately from session restore. Commands run without an implicit shell.</p>{#each draft.startup_apps as app,index}<details class="application-entry" open><summary>Startup {index+1} · {app.name||app.command||'New startup application'}</summary><div class="entry-fields"><div class="setting-row"><label for={`startup-enabled-${index}`}>Launch at sign-in</label><input id={`startup-enabled-${index}`} class="switch" type="checkbox" role="switch" bind:checked={app.enabled} /></div><div class="setting-row"><label for={`startup-name-${index}`}>Name</label><input id={`startup-name-${index}`} type="text" maxlength="128" bind:value={app.name} /></div><div class="setting-row"><label for={`startup-command-${index}`}>Executable</label><input id={`startup-command-${index}`} type="text" maxlength="1024" bind:value={app.command} /></div><div class="argument-heading"><h3>Arguments</h3><button class="quiet" disabled={app.arguments.length>=32} onclick={()=>app.arguments.push('')}>Add argument</button></div><p class="description argument-description">One nonempty argument per entry. Spaces inside an entry stay together.</p>{#each app.arguments as argument,argIndex}<div class="setting-row"><label for={`startup-arg-${index}-${argIndex}`}>Argument {argIndex+1}</label><input id={`startup-arg-${index}-${argIndex}`} type="text" maxlength="512" bind:value={app.arguments[argIndex]} /><button class="quiet" aria-label={`Remove argument ${argIndex+1} from startup ${index+1}`} onclick={()=>app.arguments.splice(argIndex,1)}>Remove</button></div>{/each}<div class="entry-actions"><button class="quiet" aria-label={`Move startup ${index+1} up`} disabled={index===0} onclick={()=>{if(draft)moveEntry(draft.startup_apps,startupOrigins,index,-1);}}>Move up</button><button class="quiet" aria-label={`Move startup ${index+1} down`} disabled={index===draft.startup_apps.length-1} onclick={()=>{if(draft)moveEntry(draft.startup_apps,startupOrigins,index,1);}}>Move down</button><button class="quiet" aria-label={`Remove startup ${index+1}`} onclick={()=>{draft?.startup_apps.splice(index,1);startupOrigins.splice(index,1);}}>Remove startup</button></div></div></details>{:else}<div class="empty-applications">No startup applications configured.</div>{/each}</section>
{/if}
</fieldset>
<footer class="apply-bar"><div><span class="status-dot" class:unsaved={dirty}></span>{dirty?'You have unapplied application changes':'Application preferences match the saved configuration'}</div><div class="apply-actions"><button class="quiet" disabled={busy||!dirty} onclick={discard}>Discard application changes</button><button class="primary" disabled={busy||!dirty} onclick={()=>apply()}>Apply application changes</button></div></footer>
{/if}
<style>
  .application-tabs{display:flex;gap:5px;flex-wrap:wrap;padding:5px;background:var(--fd-surface-muted);border:1px solid var(--fd-border);border-radius:10px;margin-bottom:25px}.application-tabs button{padding:10px 14px;border-radius:7px;font-size:12px;background:transparent;color:var(--fd-text-muted)}.application-tabs button.active{background:var(--fd-surface);color:var(--fd-accent)}.application-fields{padding:0;margin:0;border:0;min-width:0}.description{font-size:12px;line-height:1.8;color:var(--fd-text-muted);margin:12px 0 18px}input,select{font:inherit;font-size:12px;border:1px solid var(--fd-border);border-radius:8px;padding:10px;background:var(--fd-surface);color:var(--fd-text);max-width:340px;width:45%}input[type=number]{width:90px}.application-entry{border:1px solid var(--fd-border);border-radius:var(--fd-radius);background:var(--fd-surface);margin:16px 0;overflow:hidden}.application-entry summary{padding:18px 20px;cursor:pointer;font-size:13px;font-weight:600;overflow-wrap:anywhere}.entry-fields{border-top:1px solid var(--fd-border)}.entry-actions{display:flex;gap:8px;flex-wrap:wrap;padding:17px 20px}.argument-heading{display:flex;align-items:center;justify-content:space-between;padding:18px 20px 0}.argument-heading h3{font-size:12px;margin:0}.argument-description{padding:0 20px}.empty-applications{padding:25px;border:1px dashed var(--fd-border);border-radius:var(--fd-radius);color:var(--fd-text-muted);font-size:12px;line-height:1.8}.applications-prompt{padding:22px;border:1px solid var(--fd-border);border-radius:var(--fd-radius);background:var(--fd-surface);margin:20px 0}.applications-prompt p{font-size:12px;line-height:1.8;color:var(--fd-text-muted);margin:12px 0}.applications-prompt button{margin-right:8px}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}@media(max-width:600px){input,select{width:100%;max-width:none}.application-tabs button{padding:8px;font-size:10px}}
</style>
